package dev.zomboid.firstaid;
public final class Revival {
 static float raw(Object m){return ZeroParts.rawHealth(m,null);}
 public static boolean active(Object m){return R.yes(R.get(m,"criticalConditionActive"));}
 public static boolean bypass(Object source){if(source==null)return false;try{Object types=R.type("net.minecraft.world.damagesource.DamageTypes");return R.yes(R.call(source,"is",R.get(types,"GENERIC_KILL")))||R.yes(R.call(source,"is",R.get(types,"FELL_OUT_OF_WORLD")));}catch(Exception e){return false;}}
 public static boolean preventDeath(Object m,Object p,Object source){if(bypass(source))return false;if(raw(m)>0)return true;post(m,p,source);return active(m);}
 public static void bodyFatal(Object p,Object source){Object m=Assist.model(p);if(m!=null&&!preventDeath(m,p,source))R.call(R.type("ichttt.mods.firstaid.common.util.CommonUtils"),"killPlayerDirectly",p,source);}
 public static void post(Object m,Object p,Object source){if(R.yes(R.call(R.call(p,"level"),"isClientSide"))||active(m)||raw(m)>0||!R.yes(R.call(p,"isAlive"))||bypass(source))return;R.set(m,"criticalConditionActive",true);Object tag=R.call(p,"getPersistentData");R.call(tag,"putInt","FAFinishHits",0);R.call(tag,"putLong","FADownDeadline",Assist.time(p)+2000);R.call(m,"setUnconsciousState",2000,false,true,"firstaid.gui.downed_assist");R.call(m,"scheduleResync");}
 public static int nativeCountdown(int remaining,Object model){return active(model)?((Number)R.call(model,"getUnconsciousTicks")).intValue():remaining;}
 public static void clock(Object m,Object p){Object tag=R.call(p,"getPersistentData");if(!active(m)){R.call(tag,"putLong","FADownDeadline",0L);return;}long now=Assist.time(p),deadline=((Number)R.call(tag,"getLong","FADownDeadline")).longValue();if(deadline==0){deadline=now+Math.max(0,Math.min(2000,((Number)R.call(m,"getUnconsciousTicks")).intValue()));R.call(tag,"putLong","FADownDeadline",deadline);}int remaining=(int)Math.max(0,Math.min(2000,deadline-now));R.set(m,"unconsciousTicks",remaining);if(remaining==0){R.set(m,"criticalConditionActive",false);R.call(m,"clearUnconsciousState");R.call(m,"clearUnconsciousPenalties",p);R.call(tag,"putLong","FADownDeadline",0L);R.call(R.type("ichttt.mods.firstaid.common.util.CommonUtils"),"killPlayerDirectly",p,null);return;}if(now%20==0)R.call(R.type("ichttt.mods.firstaid.common.util.CommonUtils"),"syncDamageModel",p);}
 public static Object countdown(Object model,float partial){int ticks=((Number)R.call(model,"getUnconsciousTicks")).intValue();String key=active(model)?"firstaid.gui.assist_time_left":"firstaid.gui.unconscious_left";String time=String.format(java.util.Locale.ROOT,"%02d:%02d",Math.max(0,(ticks+19)/20)/60,Math.max(0,(ticks+19)/20)%60);return R.call(R.type("net.minecraft.network.chat.Component"),"translatable",key,new Object[]{time});}
 public static void tick(Object m,Object p){Assist.hearts(p);if(!active(m)&&raw(m)<=0)post(m,p,null);}
}
